#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char *name;
    int stock;
} Item;

Item *item_new(const char *name, int stock)
{
    Item *it = malloc(sizeof *it);
    if (it == NULL) return NULL;
    it->name = malloc(strlen(name) + 1);
    if (it->name == NULL) { free(it); return NULL; }
    strcpy(it->name, name);
    it->stock = stock;
    return it;
}

void item_free(Item *it)
{
    if (it == NULL) return;
    free(it->name);
    free(it);
}

int main(void)
{
    Item *ors = item_new("ORS sachets", 40);
    Item *zinc = item_new("zinc tablets", 12);
    if (ors && zinc) {
        ors->stock -= 5;
        printf("%s: %d left\n", ors->name, ors->stock);
        printf("%s: %d left\n", zinc->name, zinc->stock);
    }
    item_free(ors);
    item_free(zinc);
    return 0;
}

