typedef struct {
    char name[24];
    int stock;
    int min_stock;
} Medicine;

Medicine *stock_new(int n)
{
    if (n <= 0) return NULL;
    Medicine *m = my_alloc(n * sizeof *m);    /* one block, side by side */
    if (m == NULL) return NULL;
    memset(m, 0, n * sizeof *m);              /* empty names, zero numbers */
    return m;
}

int count_low(const Medicine *m, int n)
{
    int low = 0;
    for (int i = 0; i < n; i++)
        if (m[i].stock < m[i].min_stock) low++;
    return low;
}

