#define MAX_ENEMIES 8

typedef struct {
    char kind[16];
    int hp;
} Enemy;

typedef struct {
    Enemy *slots[MAX_ENEMIES];   /* NULL means the slot is free */
} World;

void world_free(World *w)
{
    for (int i = 0; i < MAX_ENEMIES; i++) {
        my_free(w->slots[i]);
        w->slots[i] = NULL;
    }
}

int spawn(World *w, const char *kind, int hp)
{
    for (int i = 0; i < MAX_ENEMIES; i++) {
        if (w->slots[i] != NULL) continue;
        Enemy *e = my_alloc(sizeof *e);
        if (e == NULL) return -1;
        strncpy(e->kind, kind, sizeof e->kind - 1);
        e->kind[sizeof e->kind - 1] = '\0';     /* strncpy may not add it */
        e->hp = hp;
        w->slots[i] = e;
        return i;
    }
    return -1;                                    /* every slot is taken */
}

int clear_dead(World *w)
{
    int n = 0;
    for (int i = 0; i < MAX_ENEMIES; i++) {
        if (w->slots[i] != NULL && w->slots[i]->hp <= 0) {
            my_free(w->slots[i]);
            w->slots[i] = NULL;                   /* so it's never freed twice */
            n++;
        }
    }
    return n;
}
